"""
Writes src/factoriollm/vanilla_recipes.py: the recipe names of the Factorio base game (no Space Age).

draftsman ships data with Space Age enabled, so "the recipe exists in draftsman" does not mean
"vanilla". The list is read from wube/factorio-data at a fixed tag; barrel recipes are generated by
the game at load time and are added for the base-game fluids.

    uv run python tools/extract_vanilla_recipes.py [--tag 2.0.72]
"""

from __future__ import annotations

import argparse
import re
import urllib.request
from pathlib import Path

OUT = Path(__file__).resolve().parent.parent / "src" / "factoriollm" / "vanilla_recipes.py"
URL = "https://raw.githubusercontent.com/wube/factorio-data/{tag}/base/prototypes/recipe.lua"
BASE_FLUIDS = ("crude-oil", "heavy-oil", "light-oil", "lubricant", "petroleum-gas", "sulfuric-acid", "water")


def main():
    parser = argparse.ArgumentParser(description=__doc__.splitlines()[1])
    parser.add_argument("--tag", default="2.0.72")
    args = parser.parse_args()
    with urllib.request.urlopen(URL.format(tag=args.tag), timeout=60) as response:
        source = response.read().decode("utf-8")
    names = set(re.findall(r'type\s*=\s*"recipe"\s*,\s*name\s*=\s*"([a-z0-9][a-z0-9\-]*[a-z0-9])"', source))
    names |= {f"{fluid}-barrel" for fluid in BASE_FLUIDS} | {f"empty-{fluid}-barrel" for fluid in BASE_FLUIDS}
    body = "\n".join(f'    "{n}",' for n in sorted(names))
    OUT.write_text(
        f'"""Recipe names of the Factorio base game {args.tag} (generated by tools/extract_vanilla_recipes.py)."""\n\n'
        f"VANILLA_RECIPES = frozenset({{\n{body}\n}})\n",
        encoding="utf-8",
    )
    print(f"[*] {len(names)} recipes -> {OUT}")


if __name__ == "__main__":
    main()
